import '@servicenow/sdk/global'
import { IntegerColumn, StringColumn } from '@servicenow/sdk/core'
import { FlowArray, FlowObject, Subflow, wfa } from '@servicenow/sdk/automation'

/**
 * Test subflow for assignSubflowOutputs with FlowArray
 * Tests that plain array literals can be assigned to FlowArray outputs
 */
export const assignSubflowOutputsFlowArrayTest = Subflow(
    {
        $id: Now.ID['assign-subflow-outputs-flow-array-test'],
        name: 'AssignSubflowOutputs FlowArray Test',
        description: 'Test assignSubflowOutputs with FlowArray values',
        inputs: {
            inputTag: StringColumn({ label: 'Input Tag', mandatory: false }),
        },
        outputs: {
            // FlowArray with primitive string elements
            tags: FlowArray({
                label: 'Tags',
                mandatory: false,
                elementType: StringColumn({ label: 'Tag', mandatory: false }),
                childName: 'tag',
            }),

            // FlowArray with primitive integer elements
            scores: FlowArray({
                label: 'Scores',
                mandatory: false,
                elementType: IntegerColumn({ label: 'Score', mandatory: false }),
                childName: 'score',
            }),

            // FlowArray with FlowObject elements
            users: FlowArray({
                label: 'Users',
                mandatory: false,
                elementType: FlowObject({
                    fields: {
                        name: StringColumn({ label: 'Name', mandatory: false }),
                        id: IntegerColumn({ label: 'ID', mandatory: false }),
                    },
                    label: 'User',
                    mandatory: false,
                }),
                childName: 'user',
            }),
        },
    },
    (params) => {
        // Test 1: FlowArray with primitive string literals
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign-outputs-string-array'],
                annotation: 'String array literals',
            },
            params.outputs,
            {
                tags: ['production', 'critical', 'p0'],
            }
        )

        // Test 2: FlowArray with primitive integer literals
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign-outputs-integer-array'],
                annotation: 'Integer array literals',
            },
            params.outputs,
            {
                scores: [85, 92, 78],
            }
        )

        // Test 3: FlowArray with FlowObject elements
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign-outputs-object-array'],
                annotation: 'Object array literals',
            },
            params.outputs,
            {
                users: [
                    { name: 'David', id: 10 },
                    { name: 'Emma', id: 20 },
                    { name: 'Frank', id: 30 },
                ],
            }
        )

        // Test 4: FlowArray with datapills
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign-outputs-array-datapills'],
                annotation: 'Array with datapills',
            },
            params.outputs,
            {
                tags: ['constant', wfa.dataPill(params.inputs.inputTag, 'string')],
            }
        )

        // Test 5: Empty FlowArray
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign-outputs-empty-array'],
                annotation: 'Empty array',
            },
            params.outputs,
            {
                tags: [],
            }
        )
    }
)
